//! M4 — Form XObjects and basic image XObjects (ISO 32000-1 §8.8–§8.10).
//!
//! Covers:
//!   * `Do` resolution via the effective `/Resources /XObject` dict
//!   * Form XObjects: `/Matrix`, `/BBox` clipping, own `/Resources`,
//!     nesting, recursion detection, `/Group` refusal
//!   * Image XObjects: `/DeviceGray`/`/DeviceRGB`, raw + Flate +
//!     DCTDecode, `/Decode`, clipping, dimension/data mismatches
//!   * Refusals: `/ImageMask`, `/Mask`, `/SMask`, `/OC`, unknown
//!     subtypes, missing names, oversized images
//!
//! Fixtures are generated by `tests/fixtures/make_fixtures.py` and are
//! deterministic; tests assert on rendered pixels, not PNG bytes.

use kasane_pdf::{render_page, Document, Error, Limits, RenderOptions};

fn fixture(name: &str) -> Vec<u8> {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&path).unwrap_or_else(|e| panic!("cannot read {path}: {e}"))
}

fn render(name: &str) -> Result<kasane_pdf::RenderedPage, Error> {
    let pdf = fixture(name);
    let doc = Document::from_bytes(&pdf)?;
    render_page(&doc, &doc.pages()[0], &RenderOptions::default())
}

fn render_lim(name: &str, limits: Limits) -> Result<kasane_pdf::RenderedPage, Error> {
    let pdf = fixture(name);
    let doc = Document::from_bytes(&pdf)?;
    render_page(
        &doc,
        &doc.pages()[0],
        &RenderOptions {
            limits,
            ..RenderOptions::default()
        },
    )
}

fn pixel(page: &kasane_pdf::RenderedPage, x: u32, y: u32) -> (u8, u8, u8, u8) {
    let p = page.pixmap.pixel(x, y).expect("pixel in bounds");
    (p.red(), p.green(), p.blue(), p.alpha())
}

// --------------------------------------------------------------------
// Form XObjects
// --------------------------------------------------------------------

#[test]
fn form_basic_paints() {
    // q 1 0 0 1 10 10 cm /Fm1 Do Q — form fills 0 0 50 50 red.
    // Page space (10..60, 10..60) → pixmap y flips to (40..90).
    let r = render("xobject_form_basic.pdf").unwrap();
    let (r_, g, b, a) = pixel(&r, 30, 60);
    assert_eq!((r_, g, b, a), (255, 0, 0, 255));
    let (r_, g, b, _) = pixel(&r, 5, 5);
    assert_eq!((r_, g, b), (255, 255, 255));
}

#[test]
fn form_matrix_translation() {
    // Form /Matrix [1 0 0 1 40 40] shifts a 10x10 blue square to
    // page (40..50, 40..50) → pixmap y (50..60).
    let r = render("xobject_form_matrix.pdf").unwrap();
    let (_, _, b, _) = pixel(&r, 45, 55);
    assert_eq!(b, 255);
    let (r_, g, b, _) = pixel(&r, 45, 30);
    assert_eq!((r_, g, b), (255, 255, 255));
}

#[test]
fn form_bbox_clips_content() {
    // Form paints a huge rect; BBox [10 10 30 30] clips it to 20x20.
    let r = render("xobject_form_bbox_clip.pdf").unwrap();
    let (r_, g, b, _) = pixel(&r, 20, 80); // inside BBox
    assert_eq!((r_, g, b), (255, 0, 0));
    let (r_, g, b, _) = pixel(&r, 50, 50); // outside BBox
    assert_eq!((r_, g, b), (255, 255, 255));
}

#[test]
fn form_own_resources_do_not_leak() {
    // Form with empty own /Resources still paints (rg needs no resources).
    let r = render("xobject_form_own_resources.pdf").unwrap();
    let (r_, g, b, _) = pixel(&r, 15, 85);
    assert_eq!((r_, g, b), (0, 255, 0));
}

#[test]
fn form_nested_invokes_inner() {
    // Outer cm-translates then invokes inner — blue at (20..30, 70..80).
    let r = render("xobject_form_nested.pdf").unwrap();
    let (_, _, b, _) = pixel(&r, 25, 75);
    assert_eq!(b, 255);
    let (r_, g, b, _) = pixel(&r, 5, 5);
    assert_eq!((r_, g, b), (255, 255, 255));
}

#[test]
fn form_self_recursion_rejected() {
    let err = render("xobject_form_self_recursive.pdf").unwrap_err();
    assert!(matches!(err, Error::CycleDetected { .. }), "{err:?}");
}

#[test]
fn form_group_opaque_normal_runs_inline() {
    // /Group /S /Transparency under the initial (opaque, Normal) state
    // composites exactly like direct painting (§11.4.7) — it renders.
    // The group's 10×10 black square lands at the page origin.
    let r = render("xobject_form_group.pdf").unwrap();
    assert_eq!(pixel(&r, 5, r.height - 5), (0, 0, 0, 255));
}

#[test]
fn form_group_under_alpha_is_refused() {
    // The same group under ca < 1 needs real group compositing.
    let pdf = {
        let objs: Vec<Vec<u8>> = vec![
            b"<< /Type /Catalog /Pages 2 0 R >>".to_vec(),
            b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec(),
            b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 100 100] \
               /Resources << /XObject << /FmG 5 0 R >> /ExtGState << /H << /ca 0.5 >> >> >> \
               /Contents 4 0 R >>"
                .to_vec(),
            b"<< /Length 14 >>\nstream\n/H gs /FmG Do\nendstream".to_vec(),
            b"<< /Type /XObject /Subtype /Form /BBox [0 0 100 100] \
               /Group << /S /Transparency /CS /DeviceRGB >> /Length 23 >>\nstream\n\
               0 0 0 rg 0 0 10 10 re f\nendstream"
                .to_vec(),
        ];
        let mut out = b"%PDF-1.4\n".to_vec();
        let mut offs = Vec::new();
        for (i, o) in objs.iter().enumerate() {
            offs.push(out.len());
            out.extend_from_slice(format!("{} 0 obj\n", i + 1).as_bytes());
            out.extend_from_slice(o);
            out.extend_from_slice(b"\nendobj\n");
        }
        let xref = out.len();
        out.extend_from_slice(b"xref\n0 6\n0000000000 65535 f \n");
        for o in offs {
            out.extend_from_slice(format!("{o:010} 00000 n \n").as_bytes());
        }
        out.extend_from_slice(
            format!("trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF\n").as_bytes(),
        );
        out
    };
    let doc = Document::from_bytes(&pdf).unwrap();
    let err = render_page(&doc, &doc.pages()[0], &RenderOptions::default()).unwrap_err();
    assert!(matches!(err, Error::Unsupported { .. }), "{err:?}");
}

#[test]
fn form_gs_isolation() {
    // Form sets a red fill; after Do returns, page paints with its own
    // colour — proves gs is restored (form's rg must not leak out).
    // Page: blue rect, then Do(form sets red + fills), then green rect.
    // The third rect would be red if the form's rg leaked.
    let page = b"0 0 1 rg 0 0 10 10 re f /FmLeak Do 0 1 0 rg 50 0 10 10 re f";
    let form = b"1 0 0 rg 20 0 10 10 re f";
    let pdf = {
        let mut out = Vec::new();
        out.extend_from_slice(b"%PDF-1.4\n");
        let mut offs = Vec::new();
        let bodies = [
            (1, b"<< /Type /Catalog /Pages 2 0 R >>".to_vec()),
            (2, b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>".to_vec()),
            (
                3,
                b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 100 100] \
                   /Resources << /XObject << /FmLeak 5 0 R >> >> \
                   /Contents 4 0 R >>"
                    .to_vec(),
            ),
            (
                4,
                [
                    format!("<< /Length {} >>\nstream\n", page.len()).into_bytes(),
                    page.to_vec(),
                    b"\nendstream".to_vec(),
                ]
                .concat(),
            ),
            (
                5,
                [
                    b"<< /Type /XObject /Subtype /Form /BBox [0 0 100 100] ".to_vec(),
                    format!("/Length {} >>\nstream\n", form.len()).into_bytes(),
                    form.to_vec(),
                    b"\nendstream".to_vec(),
                ]
                .concat(),
            ),
        ];
        for (n, b) in &bodies {
            offs.push((*n, out.len()));
            out.extend_from_slice(format!("{n} 0 obj\n").as_bytes());
            out.extend_from_slice(b);
            out.extend_from_slice(b"\nendobj\n");
        }
        let xref = out.len();
        out.extend_from_slice(b"xref\n0 6\n");
        out.extend_from_slice(b"0000000000 65535 f \n");
        for (_n, off) in &offs {
            out.extend_from_slice(format!("{off:010} 00000 n \n").as_bytes());
        }
        out.extend_from_slice(b"trailer\n<< /Size 6 /Root 1 0 R >>\n");
        out.extend_from_slice(format!("startxref\n{xref}\n%%EOF\n").as_bytes());
        out
    };
    let doc = Document::from_bytes(&pdf).unwrap();
    let r = render_page(&doc, &doc.pages()[0], &RenderOptions::default()).unwrap();
    // Third rect must be green — not red leaked from the form.
    let (r_, g, b, _) = pixel(&r, 55, 95);
    assert_eq!((r_, g, b), (0, 255, 0));
}

